def notification_model(self):
        """Returns the Notification 'model' instance associated
        with this notification.
        """
        if hasattr(self, "_notification_model"):
            return self._notification_model
        # Try to locate a related Notification instance.
        # Common patterns: a direct attribute, a foreign‑key field, or an ID.
        # 1. Direct attribute
        if hasattr(self, "notification"):
            self._notification_model = self.notification
            return self._notification_model
        # 2. Foreign‑key field (e.g., notification_id)
        if hasattr(self, "notification_id"):
            try:
                from .models import Notification
            except Exception:
                # Fallback: cannot import the model; return None
                self._notification_model = None
                return None
            try:
                self._notification_model = Notification.objects.get(pk=self.notification_id)
            except Notification.DoesNotExist:
                self._notification_model = None
            except Exception:
                self._notification_model = None
            return self._notification_model
        # 3. No recognizable link; cache None and return
        self._notification_model = None
        return None

