def unsubscribe_all(self, callback=False):
        """Send an unsubscribe for all active subscriptions"""
        futures = ((f, r) for f, r in self._requests.items()
                   if isinstance(r, Subscribe)
                   and f not in self._pending_unsubscribes)
        if futures:
            for future, request in futures:
                if callback:
                    log.warn("Unsubscribing from %s", request.path)
                    cothread.Callback(self.unsubscribe, future)
                else:
                    self.unsubscribe(future)

mgc_code:
def unsubscribe_all(self, callback=False):
        """Send an unsubscribe for all active subscriptions"""
        unsubscribed = []
        # Ensure we have a subscriptions container
        subs = getattr(self, "subscriptions", {})
        # Work on a copy to avoid mutation issues during iteration
        for sub_id, sub_info in list(subs.items()):
            # Send the unsubscribe request; adapt to the client's send method
            try:
                # Common unsubscribe payload; adjust keys if the client uses a different format
                payload = {"op": "unsubscribe", "args": [sub_id]}
                if hasattr(self, "send"):
                    self.send(payload)
                elif hasattr(self, "ws") and hasattr(self.ws, "send"):
                    self.ws.send(payload)
            finally:
                # Remove the subscription from the internal store
                subs.pop(sub_id, None)
                unsubscribed.append(sub_id)

