            if isinstance(row, dict):
                val = row[field]
            elif isinstance(row, (list, tuple)):
                val = row[field]
            else:
                if isinstance(field, str):
                    val = getattr(row, field)
                else:
                    val = row[field]
        except Exception:
            val = row
        cnt[val] += 1
    return dict(cnt)

