def match_host (host, domainlist):
    """Return True if host matches an entry in given domain list."""
    host = host.lower()
    for pattern in domainlist:
        if not pattern:
            continue
        pat = pattern.lower()
        if pat.startswith('.'):
            base = pat[1:]
            if host == base or host.endswith(pat):
                return True
        else:
            if host == pat:
