def left_zero_pad(s, blocksize):
    """
    Left padding with zero bytes to a given block size

    :param s:
    :param blocksize:
    :return:
    """
    if not isinstance(blocksize, int) or blocksize < 0:
        raise ValueError("blocksize must be a non‑negative integer")
    if not isinstance(s, (bytes, bytearray)):
        raise TypeError("s must be bytes or bytearray")
    length = len(s)
    if length >= blocksize:
        return bytes(s)
    pad_len = blocksize - length
    return b'\x00' * pad_len + bytes(s)

