        get phase of the pod
        :return: PodPhase enum

        """
        # Retrieve the phase string from the pod's status
        status = getattr(self, "pod", None)
        if status is None:
            return None
        phase_str = getattr(getattr(status, "status", None), "phase", None)
        if not phase_str:
            return None

        # Try to map the string to the PodPhase enum
        try:
            return PodPhase[phase_str]
        except Exception:
            # Fallback: direct attribute access (case‑insensitive)
