def abstract(cls, predstr):
        """Instantiate a Pred from its symbol string."""
        predstr = predstr.strip()
        if '(' in predstr and predstr.endswith(')'):
            name, arg_part = predstr.split('(', 1)
            name = name.strip()
            arg_part = arg_part[:-1]  # remove trailing ')'
            args = [a.strip() for a in arg_part.split(',')] if arg_part.strip() else []
        else:
            name = predstr
            args = []
        return cls(name, *args)

