def _preprocess_nodes_for_pydot(nodes_with_data):
    """throw away all node attributes, except for 'label'"""
    result = {}
    try:
        iterator = nodes_with_data.items()
    except AttributeError:
        iterator = nodes_with_data
    for node, data in iterator:
        if isinstance(data, dict):
            label = data.get('label')
            result[node] = {'label': label} if label is not None else {}
        else:
            result[node] = {}
    return result

