mgc_code:
def check_custom_concurrency(default, forced, logger=None):
    """ Get the proper concurrency value according to the default one
    and the one specified by the crawler.

    :param int default:
      default tasks concurrency

    :param forced:
      concurrency asked by crawler

    :return:
      concurrency to use.
    :rtype: int
    """
    if forced is None:
        return default

    # Try to interpret forced as an integer concurrency value
    value = None
    if isinstance(forced, int) and not isinstance(forced, bool):
        value = forced
    else:
        try:
            value = int(forced)
        except Exception:
            value = None

    if isinstance(value, int) and value > 0:
        return value

    if logger is not None:
        try:
            logger.warning(
                "Invalid concurrency value %r supplied; falling back to default %s",
                forced,
                default,
            )
        except Exception:
            pass

    return default

