def get_inner_keys(dictionary):
    """Gets 2nd-level dictionary keys

    :param dictionary: dict
    :return: inner keys
    """
    inner_keys = set()
    for value in dictionary.values():
        if isinstance(value, dict):
            inner_keys.update(value.keys())
    return inner_keys

