def fetch_by_code(self, code):
        """
        Returns data belonging to an authorization code from memcache or
        ``None`` if no data was found.

        See :class:`oauth2.store.AuthCodeStore`.

        """
        code_data = self.mc.get(self._generate_cache_key(code))

        if code_data is None:
            raise AuthCodeNotFound

        return AuthorizationCode(**code_data)

mgc_code:
def fetch_by_code(self, code):
        """
        Returns data belonging to an authorization code from memcache or
        ``None`` if no data was found.

        See :class:`oauth2.store.AuthCodeStore`.

        """
        # Construct the memcache key for the given authorization code.
        # If the class provides a custom key‑generation helper use it,
        # otherwise fall back to a simple ``auth_code:<code>`` pattern.
        if hasattr(self, "_make_key"):
            key = self._make_key("auth_code", code)
        else:
            key = f"auth_code:{code}"

        # Retrieve the stored data.  ``memcache.get`` returns ``None`` when the
        # key is missing, which matches the documented behaviour.
        try:
            return self._memcache.get(key)
        except Exception:
            # Any error interacting with memcache should be treated as a cache miss.
            return None

