def _format_listnodes(self, listnodes):
        """
        Format ListNodes and their fields into tuples that can be printed with _print_fields().
        """
        formatted = []
        for node in listnodes:
            # Use a readable representation for the node itself
            node_repr = getattr(node, "name", None)
            if node_repr is None:
                node_repr = getattr(node, "__class__", type(node)).__name__
            # Gather public attributes (exclude private and callables)
            fields = []
            for attr, value in vars(node).items():
                if attr.startswith("_"):
                    continue
                if callable(value):
                    continue
                fields.append((attr, value))
            formatted.append((node_repr, fields))
        return formatted

