mgc_code:
def load(path, cache=None, precache=False):
    """ Parse from file.
    """
    import json
    from pathlib import Path

    def _parse_content(content, suffix):
        if suffix == ".json":
            return json.loads(content)
        try:
            import yaml
        except Exception:
            yaml = None
        if suffix in {".yaml", ".yml"} and yaml is not None:
            return yaml.safe_load(content)
        return content

    p = Path(path)
    key = str(p.resolve())
    if cache is not None and key in cache:
        return cache[key]

    raw = p.read_text(encoding="utf-8")
    data = _parse_content(raw, p.suffix.lower())

    if cache is not None:
        cache[key] = data
    return data

