def validate_registry_uri(uri: str) -> None:
    """
    Raise an exception if the URI does not conform to the registry URI scheme.
    """
    import urllib.parse

    parsed = urllib.parse.urlparse(uri)
    if parsed.scheme != "registry":
        raise ValueError(f"Invalid scheme '{parsed.scheme}': expected 'registry'")
    if not parsed.netloc:
        raise ValueError("Registry URI must include a network location (host)")
    if parsed.path == "" or not parsed.path.startswith("/"):
        raise ValueError("Registry URI must have a non‑empty absolute path")
    if parsed.params or parsed.query or parsed.fragment:
        raise ValueError("Registry URI must not contain parameters, query, or fragment")

