def _consume_impl(self, data_sinks, cube, global_iter_args):
        """ Consume """
        # Determine container type for results
        if isinstance(data_sinks, dict):
            results = {}
            iterator = data_sinks.items()
        else:
            results = []
            iterator = enumerate(data_sinks)

        for key, sink in iterator:
            # Resolve callable consumption interface
            if hasattr(sink, "consume") and callable(sink.consume):
                result = sink.consume(cube, **global_iter_args)
            elif callable(sink):
                result = sink(cube, **global_iter_args)
            else:
                # Skip non‑callable sinks
                continue

            # Store result preserving original key type
            if isinstance(results, dict):
                results[key] = result
            else:
                results.append(result)

        return results

