# Attempt to retrieve from a registry attribute if present
registry = getattr(cls, "_plugins", None)
if isinstance(registry, dict) and name in registry:
    return registry[name]

# Fallback: search subclasses (including nested subclasses)
def _search(sub):
    for subclass in sub.__subclasses__():
        # Use explicit 'plugin_name' attribute if defined, else class name
        plugin_name = getattr(subclass, "plugin_name", getattr(subclass, "name", subclass.__name__))
        if plugin_name == name:
            return subclass
        result = _search(subclass)
        if result:
            return result
    return None

plugin = _search(cls)
if plugin is None:
    raise ValueError(f"Plugin '{name}' not found in {cls.__name__}")
return plugin

