def wait_for_zap(self, timeout):
        """Wait for ZAP to be ready to receive API calls."""
        import time
        deadline = time.time() + timeout
        while True:
            try:
                # A lightweight call to check ZAP's availability
                self.zap.core.version()
                return True
            except Exception:
                if time.time() >= deadline:
                    raise TimeoutError(f"ZAP not ready after {timeout} seconds")
                time.sleep(0.5)

