def validate_upload_file(ctx, opts, owner, repo, filepath, skip_errors):
    """Validate parameters for requesting a file upload."""
    import os

    # Basic type checks
    if not isinstance(owner, str) or not owner:
        raise ValueError("owner must be a non‑empty string")
    if not isinstance(repo, str) or not repo:
        raise ValueError("repo must be a non‑empty string")
    if not isinstance(filepath, str) or not filepath:
        raise ValueError("filepath must be a non‑empty string")
    if not isinstance(skip_errors, bool):
        raise TypeError("skip_errors must be a boolean")
    if opts is not None and not isinstance(opts, dict):
        raise TypeError("opts must be a dict or None")

    # File existence check
    if not os.path.isfile(filepath):
        raise FileNotFoundError(f"File not found: {filepath}")

    # Return a normalized parameter set
    return {
        "ctx": ctx,
        "opts": opts or {},
        "owner": owner,
        "repo": repo,
        "filepath": os.path.abspath(filepath),
        "skip_errors": skip_errors,
    }

