def run_extractor(*args, **kwargs):
    """
    Initializes and runs an extractor
    """
    # Determine the extractor specification
    extractor_spec = None
    if args:
        extractor_spec = args[0]
        args = args[1:]
    elif 'extractor' in kwargs:
        extractor_spec = kwargs.pop('extractor')
    else:
        raise ValueError("No extractor specified (positional arg or 'extractor' kwarg required)")

    # Resolve the extractor to a callable/class
    if isinstance(extractor_spec, str):
        # Expect a dotted path like "module.submodule.ExtractorClass"
        module_path, _, attr_name = extractor_spec.rpartition('.')
        if not module_path:
            raise ValueError(f"Invalid extractor path '{extractor_spec}'. Must be 'module.Class'")
        try:
            module = __import__(module_path, fromlist=[attr_name])
            extractor_cls = getattr(module, attr_name)
        except Exception as e:
            raise ImportError(f"Could not import extractor '{extractor_spec}': {e}") from e
    elif callable(extractor_spec):
        extractor_cls = extractor_spec
    else:
        raise TypeError("Extractor specification must be a callable or a dotted import path string")

    # Instantiate the extractor if it's a class (has __init__), otherwise use as is
    try:
        extractor = extractor_cls(*args, **kwargs)
    except TypeError:
        # If instantiation fails, assume extractor_cls is already an instance or callable
        extractor = extractor_cls

    # Run the extractor
    if hasattr(extractor, 'run') and callable(getattr(extractor, 'run')):
        return extractor.run()
    elif callable(extractor):
        return extractor()
    else:
        raise RuntimeError("Extractor does not provide a callable interface (no 'run' method or __call__)")

