mgc_code:
def encode(self, tf_graph_predictions):
    """Encodes the graph json prediction into csv.

    Args:
      tf_graph_predictions: python dict.

    Returns:
      csv string.
    """
    import csv
    from io import StringIO
    import json

    # Normalize input to a list of records
    if isinstance(tf_graph_predictions, list):
        records = tf_graph_predictions
    else:
        records = [tf_graph_predictions]

    # Determine all field names across records
    fieldnames = set()
    for rec in records:
        if isinstance(rec, dict):
            fieldnames.update(rec.keys())
    fieldnames = sorted(fieldnames)

    # Prepare CSV output
    output = StringIO()
    writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction='ignore')
    writer.writeheader()
    for rec in records:
        # Ensure each value is serializable; convert complex types to JSON strings
        row = {}
        for key in fieldnames:
            val = rec.get(key, "")
            if isinstance(val, (dict, list)):
                row[key] = json.dumps(val, separators=(",", ":"))
            else:
                row[key] = val
        writer.writerow(row)

    return output.getvalue()

