def get_creation_date(brain_or_object):
    """Get the creation date of the brain or object

    :param brain_or_object: A single catalog brain or content object
    :type brain_or_object: ATContentType/DexterityContentType/CatalogBrain
    :returns: Creation date
    :rtype: DateTime
    """
    from DateTime import DateTime

    # Catalog brain: usually has a string attribute 'CreationDate'
    if hasattr(brain_or_object, "CreationDate"):
        creation = brain_or_object.CreationDate
        return creation if isinstance(creation, DateTime) else DateTime(creation)

    # Dexterity/Archetype content object: usually has a DateTime attribute 'created'
    if hasattr(brain_or_object, "created"):
        return brain_or_object.created

    # Fallback: try to fetch a 'created' field via the schema (Archetype style)
    try:
        field = brain_or_object.getField("created")
        return field.get(brain_or_object)
    except Exception:
        raise AttributeError("Unable to determine creation date for %r" % brain_or_object)

