mgc_code:
def new_bg(self,bg):
        """
        m.new_bg(,bg)  -- Change the ACGT background frequencies to those in the supplied dictionary.
                          Recompute log-likelihood, etc. with new background.
        """
        import math

        # Validate input dictionary
        if not isinstance(bg, dict):
            raise TypeError("bg must be a dictionary mapping nucleotides to frequencies")
        required_keys = {'A', 'C', 'G', 'T'}
        if set(bg.keys()) != required_keys:
            missing = required_keys - set(bg.keys())
            extra = set(bg.keys()) - required_keys
            msgs = []
            if missing:
                msgs.append(f"missing keys: {', '.join(sorted(missing))}")
            if extra:
                msgs.append(f"unexpected keys: {', '.join(sorted(extra))}")
            raise ValueError("bg dictionary must contain exactly A, C, G, T: " + "; ".join(msgs))
        total = sum(bg.values())
        if total <= 0:
            raise ValueError("background frequencies must sum to a positive number")
        # Normalize to sum to 1
        norm_bg = {k: v / total for k, v in bg.items()}

        # Store the new background and its log values
        self.bg = norm_bg
        self.log_bg = {k: math.log(v) for k, v in norm_bg.items()}

        # Recompute any dependent statistics if the object provides a method for it
        if hasattr(self, "recalc"):
            try:
                self.recalc()
            except Exception as e:
                raise RuntimeError("Failed to recompute dependent statistics after setting new background") from e

