def get_records(cls, ids, with_deleted=False):
        """Retrieve multiple records by id.

        :param ids: List of record IDs.
        :param with_deleted: If `True` then it includes deleted records.
        :returns: A list of :class:`Record` instances.
        """
        if not ids:
            return []
        try:
            iter(ids)
        except TypeError:
            raise TypeError("ids must be an iterable of IDs")
        query = getattr(cls, "query", None)
        if query is None:
            # Fallback: use a simple get for each id
            results = []
            for _id in ids:
                try:
                    rec = cls.get(_id, with_deleted=with_deleted)  # type: ignore[attr-defined]
                    if rec is not None:
                        results.append(rec)
                except Exception:
                    continue
            return results
        q = query.filter(cls.id.in_(ids))
        if not with_deleted and hasattr(cls, "deleted"):
            q = q.filter(cls.deleted == False)  # noqa: E712
        return q.all()

