def get_text(obj) -> Tuple[int, str]:
    """
    Return text with its offset in the document

    Args:
        obj: BioCDocument, BioCPassage, or BioCSentence

    Returns:
        offset, text
    """
    from typing import Tuple

    # Import types lazily to avoid hard dependency if not needed
    try:
        from bioc import BioCDocument, BioCPassage, BioCSentence
    except Exception:
        BioCDocument = BioCPassage = BioCSentence = None

    if BioCSentence is not None and isinstance(obj, BioCSentence):
        return getattr(obj, "offset", 0), getattr(obj, "text", "")
    if BioCPassage is not None and isinstance(obj, BioCPassage):
        return getattr(obj, "offset", 0), getattr(obj, "text", "")
    if BioCDocument is not None and isinstance(obj, BioCDocument):
        # Document offset is conventionally 0; concatenate passage texts
        offset = 0
        texts = []
        for passage in getattr(obj, "passages", []):
            texts.append(getattr(passage, "text", ""))
        return offset, "".join(texts)

    # Fallback: try generic attributes
    offset = getattr(obj, "offset", 0)
    text = getattr(obj, "text", "")
    return offset, text

